import{_ as t,l as c,o as r,c as i,v as n,p as d,x as o,d as s,i as l,S as T}from"./chunks/framework.InCnrqk-.js";const _=JSON.parse('{"title":"Triton Inference Server","description":"","frontmatter":{"title":"Triton Inference Server","date":"2026-09-07T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/triton-inference-server.md","filePath":"llm/triton-inference-server.md","lastUpdated":1789023840000}'),h={name:"llm/triton-inference-server.md"};function p(m,e,b,E,g,L){const a=c("Mermaid");return r(),i("div",null,[e[1]||(e[1]=n('<h1 id="triton-inference-server" tabindex="-1">Triton Inference Server <a class="header-anchor" href="#triton-inference-server" aria-label="Permalink to &quot;Triton Inference Server&quot;">​</a></h1><div class="epigraph"><p>请求进 HTTP/gRPC 或 C API，按模型交给各自的调度器做动态批或序列批，再交给对应 backend；模型仓库是文件系统上的版本化目录，不是进程内的一张权重表。</p><footer>—— NVIDIA Triton Architecture 用户指南</footer></div><p>Triton 要解决的问题比「跑一个 Transformer」更老：数据中心里同时存在着 TensorFlow、PyTorch、ONNX、TensorRT 以及各种自定义前后处理，每家框架自带一套服务进程，批处理、健康检查和指标各写一遍。NVIDIA 从 2018 年的 TensorRT Inference Server 走到今天的 Triton，把这些收成<strong>一个推理服务器进程</strong>：模型仓库、按模型配置的调度与批、可插拔 backend、KServe 风格的 HTTP/gRPC、以及给 Kubernetes 用的就绪/存活探针。生成式 LLM 后来把流式、页式 KV 和 inflight batching 接进 TensorRT-LLM backend；但 Triton 的脊梁仍然是「仓库 + 每模型调度 + backend」，不是 vLLM 那种以 KV 块为货币的中央引擎。本篇写这条脊梁，以及它和 <a href="/llm/nvidia-dynamo">Dynamo</a> 的分工。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>在线推理的延迟账单里，框架切换与内存拷贝经常不比 GEMM 便宜。客户端若先在应用层做分词、再把 <code>input_ids</code> 发到 GPU 进程、再拉回 token 做反分词，中间两次网络往返加上两次主机/设备拷贝。多模型同时在线时，还要决定谁占用哪张卡、如何把不同到达的小请求拼成对 GPU 友好的批。每家框架自己做这些事，运维面按框架数线性涨。</p><p>LLM 把同一问题推到极端：一次请求对应<strong>多个</strong>响应（每个新 token 一次），且执行期很长。传统「一个请求一个张量输出」的事务模型会堵住其他请求的返回。需要一种解耦（decoupled）事务：backend 可以在一次 execute 里零次或多次回响应，客户端必须走双向流式 gRPC，而不是普通 HTTP 的单响应。</p><h3 id="动态批不是连续批" tabindex="-1">动态批不是连续批 <a class="header-anchor" href="#动态批不是连续批" aria-label="Permalink to &quot;动态批不是连续批&quot;">​</a></h3><p>Triton 的 dynamic batching 面向<strong>无状态</strong>模型：在 <code>max_queue_delay_microseconds</code> 窗口里把到达的请求拼成 preferred batch size，然后一次 backend 调用。这与 <a href="/llm/orca-iteration">Orca</a> / vLLM 的迭代级连续批不是同一算法——后者在每一步前向结束时允许成员进出，KV 作为跨步状态留下。Triton 用 sequence batcher 处理有状态序列（必须粘在同一 model instance），用 TensorRT-LLM 的 inflight batcher 把生成式的连续批下放到 backend 内部。混淆这三层，会在配置里打开 <code>dynamic_batching</code> 却指望它管理 KV。</p><p><span class="marginnote">「Triton 支持 LLM」不等于「Triton 实现了 PagedAttention」。分页与 inflight batching 住在 TensorRT-LLM backend（<code>inflight_batcher_llm</code>）里。Triton 负责把请求送到这个 backend，并处理流式事务与集成。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>模型仓库是带版本号的目录树。每个模型一份 <code>config.pbtxt</code>：平台或 backend 名、输入输出张量、<code>instance_group</code>（同一模型几个执行实例、放 GPU 还是 CPU）、以及可选的 <code>dynamic_batching</code> / <code>sequence_batching</code>。请求到达后，按模型名路由到该模型的调度器，调度器组批再调用 backend C API。Backend 可以是框架运行时，也可以是自定义前后处理。健康与指标从同一进程暴露，便于挂到 Kubernetes。</p><p>多步流水线有两条官方拼法。<strong>Ensemble</strong> 用 DAG 把若干模型的张量边连起来，客户端只看见 ensemble 的输入输出，分词→推理→反分词可以留在服务器侧，少一次网络往返。<strong>BLS</strong>（Business Logic Scripting）在 Python backend 里用代码决定下一步调谁，适合带控制流的管线。TensorRT-LLM 的示例仓库把 <code>preprocessing</code>、<code>tensorrt_llm</code>、<code>postprocessing</code> 收成 <code>ensemble</code>，另提供 <code>tensorrt_llm_bls</code> 作为可编程替代。</p><p>TensorRT-LLM backend 用 MPI 协调多卡。<strong>Leader 模式</strong>适合单模型占满一组 GPU；<strong>Orchestrator 模式</strong>由一个 Triton 进程拉起每卡一个 worker 进程，便于同一节点上多模型。<code>decoupled_mode</code> 打开后走流式生成；<code>batching_strategy</code> 选 <code>inflight_fused_batching</code> 一类策略时，连续批发生在 TRT-LLM executor 内，并配置 <code>max_tokens_in_paged_kv_cache</code>、<code>kv_cache_free_gpu_mem_fraction</code>、是否启用 KV 复用等。这些旋钮属于 backend，不是 Triton 核心调度器的通用字段。</p>',13)),(r(),d(T,null,{default:o(()=>[l(a,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22HTTP%20%2F%20gRPC%20%2F%20C%20API%22%5D%20--%3E%20R%5B%22%E6%8C%89%E6%A8%A1%E5%9E%8B%E8%B7%AF%E7%94%B1%22%5D%0A%20%20R%20--%3E%20S%5B%22%E6%AF%8F%E6%A8%A1%E5%9E%8B%E8%B0%83%E5%BA%A6%E5%99%A8%22%5D%0A%20%20S%20--%3E%20DB%5B%22%E5%8A%A8%E6%80%81%E6%89%B9%20%C2%B7%20%E6%97%A0%E7%8A%B6%E6%80%81%22%5D%0A%20%20S%20--%3E%20SB%5B%22%E5%BA%8F%E5%88%97%E6%89%B9%20%C2%B7%20%E6%9C%89%E7%8A%B6%E6%80%81%22%5D%0A%20%20DB%20--%3E%20BE%5B%22Backend%22%5D%0A%20%20SB%20--%3E%20BE%0A%20%20BE%20--%3E%20ENS%5B%22Ensemble%20%2F%20BLS%20%E6%B5%81%E6%B0%B4%E7%BA%BF%22%5D%0A%20%20BE%20--%3E%20TRT%5B%22TRT-LLM%20inflight%20batcher%22%5D%0A%20%20TRT%20--%3E%20KV%5B%22%E5%88%86%E9%A1%B5%20KV%EF%BC%88backend%20%E5%86%85%EF%BC%89%22%5D%0A"})]),fallback:o(()=>[...e[0]||(e[0]=[s(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=n('<h3 id="解耦事务与客户端协议" tabindex="-1">解耦事务与客户端协议 <a class="header-anchor" href="#解耦事务与客户端协议" aria-label="Permalink to &quot;解耦事务与客户端协议&quot;">​</a></h3><p>官方文档写明：解耦模型不能用 Triton&#39;s HTTP 推理端点（它假定恰好一个响应），标准 gRPC <code>ModelInfer</code> 也不行；必须用双向流式 RPC。响应完成靠 <code>TRITONSERVER_RESPONSE_COMPLETE_FINAL</code> 一类标志。这对 LLM 网关意味着：OpenAI 兼容的 SSE 若接在 Triton 前面，网关要自己把流式 gRPC 译成 token 事件；不要假设 <code>v2/models/.../infer</code> 能流式吐词。ASR 等「一请求多响应」的模型是同一套事务语义的先驱，LLM 只是把响应次数拉到生成长度。</p><p>并发执行靠 <code>instance_group</code>：同一模型多实例可以同时跑，动态批把请求洒到这些实例上。过小的 instance 数会让 GPU 在排队；过大则权重副本占显存。LLM 的 TRT-LLM 路径通常一个模型占一组 GPU，多模型并存走 Orchestrator，而不是在同一组卡上堆许多 instance。</p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>Triton 的加速来自<strong>把组批与拷贝上收到服务进程</strong>，让 backend 看到更饱和的张量，而不是来自某条新的注意力公式。无状态视觉模型上，窗口内到达的小图拼成一批，Tensor Core 利用率上升。有状态对话上，sequence batcher 保证同一会话粘在能看见隐状态的 instance 上——这是 <a href="/llm/decode-affinity">decode 亲和</a> 在「通用推理服务器」里的旧形式，只是状态那时还不是 Transformer KV。</p><p>Ensemble 的机制是服务器侧的 DAG 执行：张量在步骤之间留在设备或被框架认可的共享缓冲里转交，避免「出 GPU → 进网络 → 再进 GPU」。LLM 的 preprocessing 若用 CPU 分词，这一步仍在主机；收益是客户端不必实现与训练一致的 tokenizer，版本跟着模型仓库走。</p><p><span class="marginnote">KServe 协议让 Triton 可以和别的推理运行时互换客户端。它不保证性能模型相同。用同一份 HTTP 测试套去对比 Triton+TRT-LLM 与 vLLM，要比的是端到端 TTFT/ITL，而不是「谁更符合 KServe」。</span></p><h3 id="和-dynamo-的继承关系" tabindex="-1">和 Dynamo 的继承关系 <a class="header-anchor" href="#和-dynamo-的继承关系" aria-label="Permalink to &quot;和 Dynamo 的继承关系&quot;">​</a></h3><p>NVIDIA 自己把 Dynamo 写成 Triton 在分布式生成式场景上的后继编排：Triton 解决多框架统一与单机吞吐，Dynamo 解决跨节点 PD 分离、KV 感知路由与分层卸载。已有 Triton 企业用户继续走 NVIDIA AI Enterprise 的生产支持；新的多节点推理模型部署被指向 Dynamo。两者可以在集群里并存：Triton 继续伺候分类、嵌入、ASR ensemble，LLM 生成走 Dynamo 或直接走 vLLM/SGLang。不要把 Dynamo 理解成 Triton 的一个 backend 名。</p><h2 id="边界与工程取舍" tabindex="-1">边界与工程取舍 <a class="header-anchor" href="#边界与工程取舍" aria-label="Permalink to &quot;边界与工程取舍&quot;">​</a></h2><p>Triton 核心不知道 token 预算、前缀树或 goodput。把 DistServe 式的双 SLO 搜索写进 <code>config.pbtxt</code> 没有对应字段。动态批的 <code>max_queue_delay</code> 对短请求是延迟税，对 GPU 是吞吐补贴；LLM 的 token 级延迟通常由 inflight batcher 与 CUDA graph 决定，再叠一层动态批窗口往往有害。解耦模式下若 backend 在 <code>ModelInstanceExecute</code> 返回前不保持「还能接下一批评」的契约，动态批会退化成过早组批，官方文档对此有明确警告。</p><p>多机 TRT-LLM 依赖 MPI 拓扑。Leader 与 Orchestrator 选错，会出现「第二个模型起不来」或「world size 不是 1」。KV 复用、分页容量、beam width 全是 backend 配置，Triton 模型管理 API 只能加载/卸载整个模型，不能按块做缓存淘汰。需要集群级 KV 池时，应接到 Mooncake / Dynamo KV Manager / <a href="/llm/lmcache">LMCache</a>，而不是扩展 <code>config.pbtxt</code>。</p><p>指标默认偏吞吐与 GPU 利用率，缺少 LLM 服务关心的 KV 占用、前缀命中、P99 ITL。生产要在 backend 或旁路把这些打到同一套 Grafana，否则 Triton 仪表盘显示「GPU 90%」时，用户已经在等长前填。</p><p><span class="marginnote">出处钉 NVIDIA <em>Triton Architecture</em> 用户指南、<em>Decoupled Backends and Models</em>、TensorRT-LLM Backend README（<a href="https://github.com/triton-inference-server/tensorrtllm_backend%EF%BC%89%EF%BC%8C%E4%BB%A5%E5%8F%8A%E6%9C%8D%E5%8A%A1%E5%99%A8%E4%BB%93%E5%BA%93" target="_blank" rel="noreferrer">https://github.com/triton-inference-server/tensorrtllm_backend），以及服务器仓库</a> <a href="https://github.com/triton-inference-server/server%E3%80%82Inflight" target="_blank" rel="noreferrer">https://github.com/triton-inference-server/server。Inflight</a> batching 的算法来源是 Orca 与后续生成式引擎，不是 Triton 核心论文。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Triton 用文件系统模型仓库、每模型调度器和可插拔 backend 统一多框架在线推理。</li><li>动态批服务无状态模型；序列批服务有状态粘滞；LLM 的连续批在 TRT-LLM inflight backend 内。</li><li>Ensemble / BLS 把分词与反分词留在服务器侧；流式生成必须走解耦事务与双向 gRPC。</li><li>多卡 TRT-LLM 分 Leader 与 Orchestrator 两种 MPI 模式。</li><li>分布式 PD、KV 路由与分层卸载交给 Dynamo；Triton 仍覆盖单机多模型与非生成式管线。</li><li>出处：NVIDIA Triton 架构文档与 <code>triton-inference-server/server</code>。</li></ul>',16))])}const A=t(h,[["render",p]]);export{_ as __pageData,A as default};
